import 'service.dart';
class FeedbackState {
  final String _comment = '';
  bool _sending = false;
  String? _error;
  bool get canSend => _comment.length <= AppReviewService.maxFeedbackLength;
  int readCached() => AppReviewService.cached;
  int readMethod() => AppReviewService.method();
}

